using System.Collections.Concurrent;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using RuneshapePriceChecker.Startup;
using Microsoft.Extensions.Logging;

namespace RuneshapePriceChecker.OCR;

public sealed record CaptureResult(Bitmap Bitmap, string Method);

internal sealed partial class OcrCaptureStrategy(ILogger<OcrCaptureStrategy> logger)
{
    private readonly ILogger<OcrCaptureStrategy> _logger = logger;
    internal static readonly ConcurrentDictionary<string, byte> FailedModes = new(StringComparer.OrdinalIgnoreCase);

    public CaptureResult? Capture(OcrCaptureRegion region, WindowCaptureContext? context, OcrOptions options)
    {
        _logger.LogTrace("Capture: region=({X},{Y} {W}x{H}) mode={Mode}",
            region.X, region.Y, region.Width, region.Height, options.CaptureMode);

        if (LosslessScaling.IsRunning)
        {
            _logger.LogTrace("Capture: LosslessScaling active, using desktop capture");
            if (TryDesktopOnly(region, out var desktopResult))
                return desktopResult;

            return TryPrintWindowFallback(context, region);
        }

        var mode = options.CaptureMode?.ToLowerInvariant() ?? "printwindow";

        if (mode == "desktop")
        {
            if (TryDesktopOnly(region, out var desktopResult))
                return desktopResult;

            _logger.LogWarning("Desktop capture failed; trying PrintWindow fallback.");
            return TryPrintWindowFallback(context, region);
        }

        if (context is not null && mode == "printwindow")
        {
            _logger.LogTrace("GDI: TryPrintWindow enter");
            if (TryPrintWindow(context, region, out var pwBmp))
            {
                _logger.LogTrace("GDI: TryPrintWindow OK");
                _ = FailedModes.TryRemove("printwindow", out _);
                _logger.LogTrace("Capture: PrintWindow succeeded ({W}x{H})", pwBmp.Width, pwBmp.Height);
                return new CaptureResult(pwBmp, "window-printwindow");
            }
            _logger.LogTrace("GDI: TryPrintWindow failed");
            _ = FailedModes.TryAdd("printwindow", 0);
            _logger.LogWarning("PrintWindow capture failed — falling back to Desktop.");
            if (TryDesktopOnly(region, out var desktopResult))
                return desktopResult;

            _logger.LogWarning("Desktop fallback capture failed; no capture frame is available.");
            return null;
        }

        _logger.LogTrace("GDI: fallback desktop capture");
        return TryDesktopOnly(region, out var fallbackResult) ? fallbackResult : null;
    }

    private CaptureResult? TryPrintWindowFallback(WindowCaptureContext? context, OcrCaptureRegion region)
    {
        if (context is null)
        {
            _logger.LogWarning("Desktop capture failed and PrintWindow fallback is unavailable because no window context exists.");
            return null;
        }

        if (TryPrintWindow(context, region, out var printWindowBitmap))
        {
            _ = FailedModes.TryRemove("printwindow", out _);
            _logger.LogWarning("Desktop capture failed; using PrintWindow fallback.");
            return new CaptureResult(printWindowBitmap, "window-printwindow-fallback");
        }

        _ = FailedModes.TryAdd("printwindow", 0);
        _logger.LogWarning("Desktop capture failed and PrintWindow fallback also failed; no capture frame is available.");
        return null;
    }

    private bool TryPrintWindow(WindowCaptureContext context, OcrCaptureRegion region, out Bitmap bitmap)
    {
        bitmap = null!;
        try
        {
            _logger.LogTrace("TryPrintWindow: source=({SX},{SY}) region=({RW}x{RH})",
                region.X - context.ClientX, region.Y - context.ClientY,
                region.Width, region.Height);

            if (TryCaptureWithPrintWindow(context, region, out bitmap))
            {
                _logger.LogTrace("TryPrintWindow: captured {W}x{H}",
                    bitmap.Width, bitmap.Height);

                if (!IsLikelyInvalidCapture(bitmap))
                    return true;
                _logger.LogWarning("PrintWindow: captured bitmap is invalid (all same color or near-black).");
                bitmap.Dispose();
            }

            bitmap = null!;
            return false;
        }
        catch (Exception ex)
        {
            bitmap?.Dispose();
            bitmap = null!;
            _logger.LogWarning(ex, "PrintWindow capture failed.");
            return false;
        }
    }

#pragma warning disable CA2000 // Ownership transferred to CaptureResult
    private bool TryDesktopOnly(OcrCaptureRegion region, out CaptureResult result)
    {
        result = null!;
        Bitmap? bitmap = null;
        try
        {
            bitmap = new Bitmap(region.Width, region.Height, PixelFormat.Format24bppRgb);
            using (var graphics = Graphics.FromImage(bitmap))
            {
                graphics.CopyFromScreen(
                    region.X,
                    region.Y,
                    0,
                    0,
                    new Size(region.Width, region.Height),
                    CopyPixelOperation.SourceCopy);
            }

            result = new CaptureResult(bitmap, "desktop-copyfromscreen");
            bitmap = null;
            _ = FailedModes.TryRemove("desktop", out _);
            return true;
        }
        catch (Exception ex)
        {
            bitmap?.Dispose();
            _ = FailedModes.TryAdd("desktop", 0);
            _logger.LogWarning(ex, "Desktop CopyFromScreen capture failed.");
            return false;
        }
    }
#pragma warning restore CA2000

    public static bool IsLikelyInvalidCapture(Bitmap bitmap)
    {
        var rect = new Rectangle(0, 0, bitmap.Width, bitmap.Height);
        var data = bitmap.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
        try
        {
            var absStride = Math.Abs(data.Stride);
            var length = absStride * data.Height;
            var bytes = new byte[length];
            Marshal.Copy(data.Scan0, bytes, 0, length);

            var min = 255;
            var max = 0;
            var nearBlack = 0;
            var total = data.Width * data.Height;

            for (var y = 0; y < data.Height; y++)
            {
                var row = y * absStride;
                for (var x = 0; x < data.Width; x++)
                {
                    var index = row + (x * 3);
                    var luminance = bytes[index];

                    if (luminance < min)
                    {
                        min = luminance;
                    }

                    if (luminance > max)
                    {
                        max = luminance;
                    }

                    if (luminance < 8)
                    {
                        nearBlack++;
                    }
                }
            }

            var dynamicRange = max - min;
            var nearBlackRatio = total == 0 ? 1d : (double)nearBlack / total;

            return dynamicRange < 8 || nearBlackRatio > 0.995d;
        }
        finally
        {
            bitmap.UnlockBits(data);
        }
    }

    private bool TryCaptureWithPrintWindow(WindowCaptureContext context, OcrCaptureRegion absoluteRegion, out Bitmap bitmap)
    {
        bitmap = null!;

        var sourceX = absoluteRegion.X - context.ClientX;
        var sourceY = absoluteRegion.Y - context.ClientY;

        if (sourceX < 0 || sourceY < 0)
        {
            _logger.LogTrace("GDI: PrintWindow source out of bounds");
            return false;
        }

        if (sourceX + absoluteRegion.Width > context.ClientWidth ||
            sourceY + absoluteRegion.Height > context.ClientHeight)
        {
            _logger.LogTrace("GDI: PrintWindow region exceeds client area");
            return false;
        }

        _logger.LogTrace("GDI: PrintWindow new Bitmap({W}x{H})", context.ClientWidth, context.ClientHeight);
        using var clientBitmap = new Bitmap(context.ClientWidth, context.ClientHeight, PixelFormat.Format24bppRgb);
        _logger.LogTrace("GDI: PrintWindow Graphics.FromImage");
        using (var graphics = Graphics.FromImage(clientBitmap))
        {
            _logger.LogTrace("GDI: PrintWindow GetHdc");
            var hdc = graphics.GetHdc();
            try
            {
                _logger.LogTrace("GDI: PrintWindow calling PrintWindow native (may block)");
                const uint pwClientOnly = 0x00000001;
                const uint pwRenderFullContent = 0x00000002;
                var captured = NativeMethods.PrintWindow(context.WindowHandle, hdc, pwClientOnly | pwRenderFullContent);
                _logger.LogTrace("GDI: PrintWindow native returned captured={Captured}", captured);
                if (!captured)
                {
                    return false;
                }
            }
            finally
            {
                _logger.LogTrace("GDI: PrintWindow ReleaseHdc");
                graphics.ReleaseHdc(hdc);
            }
        }

        var cropRect = new Rectangle(sourceX, sourceY, absoluteRegion.Width, absoluteRegion.Height);
        _logger.LogTrace("GDI: PrintWindow Clone({X},{Y} {W}x{H})", cropRect.X, cropRect.Y, cropRect.Width, cropRect.Height);
        bitmap = clientBitmap.Clone(cropRect, PixelFormat.Format24bppRgb);
        _logger.LogTrace("GDI: PrintWindow clone OK ({W}x{H})", bitmap.Width, bitmap.Height);
        return true;
    }

    public static void SaveBitmapWithOverwrite(Bitmap bitmap, string path)
    {
        if (File.Exists(path))
        {
            File.Delete(path);
        }

        bitmap.Save(path, ImageFormat.Png);
    }

    private static class NativeMethods
    {
        [DllImport("user32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        public static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, uint nFlags);
    }
}

